const MONOGRAM_COLORS = [
  "#ef4444",
  "#f97316",
  "#f59e0b",
  "#eab308",
  "#84cc16",
  "#22c55e",
  "#10b981",
  "#14b8a6",
  "#06b6d4",
  "#0ea5e9",
  "#3b82f6",
  "#6366f1",
  "#8b5cf6",
  "#a855f7",
  "#d946ef",
  "#ec4899",
  "#f43f5e",
  "#fb7185",
];

export function ProviderMonogram({
  name,
  className,
  index = 0,
  ...props
}: React.SVGProps<SVGSVGElement> & { name: string; index?: number }) {
  const initials = name
    .replace(/[^a-zA-Z0-9 ]/g, "")
    .split(/[ -]/)
    .filter(Boolean)
    .slice(0, 2)
    .map((w) => w[0]?.toUpperCase())
    .join("");
  const color = MONOGRAM_COLORS[index % MONOGRAM_COLORS.length];
  return (
    <svg viewBox="0 0 24 24" className={className} {...props}>
      <rect x="1" y="1" width="22" height="22" rx="6" fill={color} />
      <text
        x="12"
        y="12"
        dominantBaseline="central"
        textAnchor="middle"
        fontSize="10"
        fontWeight="700"
        fill="#fff"
        fontFamily="ui-sans-serif, system-ui, sans-serif"
      >
        {initials}
      </text>
    </svg>
  );
}
